export interface CandidateEntry {
  id: string;
  authorName: string;
  pieceTitle: string;
  category: string;
  theme?: string;
  excerpt: string;
  fullContent?: string;
  authorBio?: string;
}

// 15-minute rotation seed generator
export function getCurrentTimeSeed(): number {
  return Math.floor(Date.now() / (15 * 60 * 1000));
}

// Deterministically rotates/shuffles candidates every 15 minutes so all entries get equal top exposure
export function getRotatedCandidates(candidates: CandidateEntry[], seed: number): CandidateEntry[] {
  if (!candidates || candidates.length <= 1) return candidates;
  const arr = [...candidates];
  let s = Math.abs(seed) || 1;
  const prng = () => {
    s = (s * 9301 + 49297) % 233280;
    return s / 233280;
  };

  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(prng() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

